import { writeFile, readFile } from "node:fs/promises";
import { bootstrapRuntime } from "../src/bootstrap-runtime.js";
const target = new URL("../src/bootstrap-runtime-source.ts", import.meta.url);
const expected =
  "// Generated by scripts/generate-bootstrap.mjs. Edit bootstrap-runtime.js, then npm run generate.\n" +
  "// Keep VM code as data so Metro/Babel cannot inject host-only helpers into it.\n" +
  "export const BOOTSTRAP_RUNTIME_SOURCE: string = " +
  JSON.stringify(bootstrapRuntime.toString().replaceAll("\r\n", "\n")) +
  ";\n";
if (process.argv.includes("--check")) {
  if ((await readFile(target, "utf8")) !== expected)
    throw Error("Bootstrap source is stale: run npm run generate");
} else await writeFile(target, expected);
